// Builds worker/dist/index.bundle.js — a single-file version of index.js with
// its local modules inlined, for pasting into the Cloudflare dashboard's "Edit
// code" editor (which only accepts one file). The multi-file source stays the
// real source of truth in git; this is a build output, regenerated by running:
//   node worker/build-bundle.mjs
//
// Mechanical, not a general bundler. Each module listed in MODULES must have no
// imports of its own; this strips their `export` keywords and prepends them to
// index.js with the matching `import ... from "./x.js"` line removed. Order
// matters only in that every module lands above all of index.js.

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const dir = path.dirname(fileURLToPath(import.meta.url));

// Add a module here when index.js starts importing one. Nothing else to change.
const MODULES = ["pricing.js", "leadpipeline.js"];

let indexSrc = fs.readFileSync(path.join(dir, "index.js"), "utf8");
let inlined = "";

for (const mod of MODULES) {
  const src = fs.readFileSync(path.join(dir, mod), "utf8");
  const importRe = new RegExp(
    '^import \\{[^}]*\\} from "\\./' + mod.replace(".", "\\.") + '";\\n',
    "m"
  );
  if (!importRe.test(indexSrc)) {
    throw new Error("Could not find the " + mod + " import line in index.js — bundler is out of sync, fix by hand.");
  }
  const stripped = src
    .replace(/^export function /gm, "function ")
    .replace(/^export async function /gm, "async function ")
    .replace(/^export const /gm, "const ")
    .replace(/^export let /gm, "let ");
  if (/^export /m.test(stripped)) {
    throw new Error(mod + " has an export form the bundler doesn't handle: " + stripped.match(/^export .*/m)[0]);
  }
  indexSrc = indexSrc.replace(importRe, "");
  inlined +=
    "// ---- inlined from worker/" + mod + " by build-bundle.mjs — do not edit below by hand ----\n" +
    stripped + "\n// ---- end inlined " + mod + " ----\n\n";
}

const bundled = inlined + indexSrc;

const outDir = path.join(dir, "dist");
fs.mkdirSync(outDir, { recursive: true });
const outPath = path.join(outDir, "index.bundle.js");
fs.writeFileSync(outPath, bundled);
console.log("Wrote " + outPath + " (" + bundled.split("\n").length + " lines, " + MODULES.length + " modules inlined)");
